data.query:
query Workunit($where: WorkunitWhereInput, $after: String) {
  workunit(
    where: $where
    orderBy: {field: updatedAt, direction: desc}
    first: 1
    after: $after
  ) {
    edges {
      node {
        id
        scheduleGroupId
        currentModeId
        currentStateId
        disabledStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
        idleStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
        otherStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
        changeoverStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
        productionStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
        maintenanceStateList{
          stateListStates{
            edges{
              node{
                stateId
              }
            }
          }
        }
      }
    }
  }
}

