data.query:
query($wherePS:ProductionSetupWhereInput, $whereM: ModeListWhereInput){
  productionSetup(where: $wherePS){
    edges{
      node{
        id
        workcenter {
          shiftGroupId
        }
        mode {
          id
          name
          modeType {
            changeover
            production
          }
        }
        eventId
        operators(
          where: {
            operatorActivity: {
              includeLabor: {
                _eq:true      
              }
            }
          }
        ){
          edges{node{id employeeId operatorActivityId laborWeight}}
        }
       outputs {
          edges {
            node {
              kanbanCard {
                id
                kanbanRack {
                  productStrategyProcess {id standardRate productionOperators setupOperators}
                }

              }
              workOrderDistributionGroup{
                id
                distributions(where: {
                  virtual: {
                    _eq: false
                  }
                }){
                  edges {
                    node {
                      id
                      laborUsage
                      machineUsage

                      standardRate
                      productionOperators
                      setupOperators

                    }
                  }
                }
              }
            }
          }
        }
      }
    }
  }
  modeList(where:$whereM, first:1){
    edges{
      node {
        mode{
          id
          name
          modeType {
            changeover
            production
          }
        }
        defaultEvent {
          id name
        }

      }
    }
  }

}

