        },
        "update": {
          "currentStateId": $state,
          "currentModeId": $mode
        }
      }
    ],
    "payloadWSH": [
      {
        "create": 
        {
          "message": $note? $note :
            $change ? "Workcenter Mode Changed to " & $mode : "Workcenter State Update to " & $state,
          "occurAt": $L.time,
          "modeId": $mode,
          "stateId": $state,
          "scheduleId": $scheduleId,
          "workunitId": $R.workunitId,
          /* "blockingWorkunitId": "",
          "starvingWorkunitId": "", */
          "productionRunId": $R.productionRunId,
          "transactionTypeId": $change ? "Mode Change" : "State Update"


        }
      }
    ]
  };
)

